"""Named historical magnetic companion, composed with unchanged native execution.

Physical observations and the authoritative investigator model ledger stay in the
parent. No benchmark policy, instrument physics, world sampling or lab access.
"""
from __future__ import annotations

import copy
import hashlib
import json
import subprocess
from pathlib import Path

from ..contracts import ConflictError
from .controller import ScientificExecutionError, encoded, signature
from .feedback import forecast_issues, public_diagnostics
from .hybrid_tools import HybridInvestigator, NO_MODEL, _CompanionCampaign

NAME = "magnetic"
UNITS = {"density_g_cm3": "g/cm^3", "grain_size_nm": "nm", "grain_d90_nm": "nm",
         "coarse_number_fraction": "1", "porosity_area_fraction": "1",
         "hci_kOe": "kOe", "br_kGs": "kGs", "bhmax_MGOe": "MGOe", "hci_screen_kOe": "kOe"}


def executable_contracts():
    return {"version": "physical-hybrid-tools-v4", "tools": "read_sources, read_evidence, read_model and inspect_state return hash-bound JSON text pages; follow next_offset; offsets/limits are characters. read_artifact uses byte offsets.",
            "compute": {"entry": "Set RESULT to a finite JSON object", "payload": ["request", "evidence", "investigation_state", "sources", "inputs"],
                        "artifacts": "artifact_sha256s mounts exact visible bytes at /workspace/raw/SHA256; RESULT.artifact_paths exports scratch files"},
            "forecast": {"entry": "def forecast(payload)", "return": {"predictions": [{"specimen_id": "each requested identity exactly once",
                "density_g_cm3": {"mean": None, "sd": None, "unit": "g/cm^3", "status": "abstained", "reason": "required when mean null"},
                "grain_size_nm": {"mean": None, "sd": None, "unit": "nm", "status": "abstained", "reason": "required when mean null"}}]},
                "numerical_fields": "mean and sd are finite nonnegative or null; explicit nonempty status. Null mean requires null sd and a reason. Numeric mean may have null sd but cannot have abstention status. Include measurement_stage for the quantity's endpoint; sd alone makes no probability claim.",
                "optional_quantities": "Same mean/sd/unit/status schema for selected supported scalar quantities. coarse_number_fraction requires positive coarse_threshold_nm. Fractions lie in [0,1]. Explicit omission remains different from abstention.",
                "adoption": "stage_model then adopt_model tests twice and freezes source plus selected artifact hashes. submit_batch uses that active model; virtual exploration without an active model records abstention."},
            "request": {"required": ["lot_id", "origin", "specimens"], "origin": ["physical", "synthetic"],
                "specimen_required": ["specimen_id", "preparation_id", "cycle_id", "conditions"],
                "operation": ["manufacture", "measure", "anneal"],
                "selection": "Use measurements list on each specimen or request. Existing-body requests declare input_stage/output_stage; measurement cannot change stage. Omit optional prior_processing_conditions to bind released canonical history.",
                "material": "consumed_mass_g, destructive, specimen_available belong on specimen, not conditions. Unknown remaining mass is not replaced with charge mass.",
                "physical": "submit_batch commits HOLD only; no equipment or RPI acceptance",
                "virtual": "request_simulation uses separate virtual IDs; simulation=magnetic selects historical reference, omitted/legacy selects preserved conditional laboratory"}}


def open_companion(parent):
    root = parent.campaign.store.path.parent / "simulation-magnetic"
    config = root / "owner_simulation_runtime.json"
    if not config.is_file():
        return None
    view = object.__new__(MagneticCompanion)
    view.__dict__ = parent.__dict__.copy()
    view.parent = parent
    view.simulation_root = root
    view.owner_simulation = json.loads(config.read_text())
    if json.loads((root / "reference_world.json").read_text()) != view.owner_simulation["world_config"]:
        raise ValueError("magnetic reference file differs from its declared owner configuration")
    view.simulation = _CompanionCampaign.open(root / "campaign")
    view.simulation.investigator_campaign = parent.campaign
    if view.simulation.config.get("execution_mode") != "synthetic":
        view.simulation.close()
        raise ValueError("magnetic companion requires an existing synthetic Campaign")
    return view


def select_companion(parent, arguments):
    name = arguments.get("simulation", "legacy")
    if name == "legacy":
        return parent
    if name != NAME:
        raise ValueError("simulation must be legacy or magnetic")
    if isinstance(parent, MagneticCompanion):
        return parent
    if parent.magnetic is None:
        raise ValueError("named magnetic companion is not configured")
    return parent.magnetic


class MagneticCompanion(HybridInvestigator):
    """A method view sharing the parent DB/model ledger, with its own virtual store."""

    def _payload(self, request=None, inputs=None):
        payload = self.parent._payload(request=request, inputs=inputs)
        payload["selected_virtual_laboratory"] = NAME
        return payload

    def _computation_artifacts(self):
        return self.parent._computation_artifacts()

    def _artifact_binding(self, digest):
        return self.parent._artifact_binding(digest)

    def artifacts(self):
        return [{**row, "evidence_class": "conditional_computational", "origin": "synthetic",
                 "physical_execution": False, "simulation": NAME,
                 "execution_id": "magnetic-" + row["delivery_id"],
                 "receipt_relative_path": "blobs/" + row["sha256"]}
                for row in self.simulation.artifacts()]

    def public_state(self, summary=False):
        state = self.simulation.state()
        common = {"campaign_id": state["campaign_id"], "simulation": NAME,
                  "origin": "synthetic", "evidence_class": "conditional_computational",
                  "physical_execution": False, "resources": state["resources"],
                  "shared_investigator_model_id": self.campaign.state()["active_model_id"],
                  "capabilities": copy.deepcopy(self.owner_simulation["public_capabilities"])}
        if summary:
            return {**common, "request_count": len(state["requests"]), "evidence_count": len(state["evidence"]),
                    "artifact_count": len(self.artifacts()),
                    "retrieval": "inspect_state(section='simulation_magnetic') for all histories, evidence and raw artifacts"}
        return {**state, **common, "artifacts": self.artifacts()}

    def diagnostics(self, request_id):
        report = public_diagnostics(self.simulation.request(request_id), self.simulation.evidence(), units=UNITS)
        return {**report, "simulation": NAME, "origin": "synthetic", "physical_execution": False,
                "evidence_class": "conditional_computational", "campaign_id": self.simulation.config["campaign_id"]}

    def public_feedback(self):
        rows = []
        for request in self.simulation.state()["requests"][-5:]:
            if not request["released_delivery_ids"]:
                continue
            report = self.diagnostics(request["request_id"])
            rows.append({"request_id": report["request_id"], "counts": report["counts"],
                         "diagnostic_errors": report["diagnostic_errors"],
                         "retrieval": "inspect_feedback(request_id='magnetic:" + report["request_id"] + "')"})
        return {"simulation": NAME, "origin": "synthetic", "physical_execution": False,
                "recent_released_requests": rows, "evidence_class": "conditional_computational"}

    def _environment(self):
        # The accepted interpreter supplies its own package and native dependency
        # closure. Never inherit a candidate PYTHONPATH into that execution.
        return {"PATH": "/usr/bin:/bin", "LANG": "C.UTF-8", "PYTHONNOUSERSITE": "1",
                "PYTHONDONTWRITEBYTECODE": "1"}

    def _contract_preview(self, request):
        state = self.simulation.state()
        payload = {"request": request, "state": {"specimen_histories": state["specimen_histories"],
                                                  "resources": state["resources"]},
                   "sources": {"task": self.owner_simulation["preview_task"]}}
        code = ("import json,sys; from ndfeb_sps.investigation.feedback import request_preview; "
                "p=json.load(sys.stdin); print(json.dumps(request_preview(p['request'],p['state'],p['sources']),allow_nan=False))")
        result = subprocess.run([self.owner_simulation["python"], "-B", "-c", code],
                                input=encoded(payload), text=True, capture_output=True,
                                env=self._environment(), check=False)
        if result.returncode:
            raise RuntimeError("magnetic contract service failed: " + result.stderr[-2000:])
        return json.loads(result.stdout)

    def _preview(self, args):
        if args["request"].get("origin") != "synthetic":
            raise ValueError("magnetic virtual preview requires origin synthetic")
        request = json.loads(encoded(args["request"]))
        result = self._contract_preview(request)
        result.update(status="read_only_preview", simulation=NAME, campaign_mutated=False,
                      experiment_executed=False, provisional_prediction=True,
                      evidence_class="conditional_computational", inference_resources=self.inference_resources())
        prediction = args.get("prediction")
        if prediction is not None and "source_sha256" in args:
            result["errors"].append("provide prediction or source_sha256, not both")
        elif prediction is None and not result["errors"]:
            request = self._virtual_request(request)
            active = self.campaign.state()["active_model_id"]
            model = self.campaign.model(active) if active else None
            source = (self._model_source(args["source_sha256"]) if "source_sha256" in args
                      else model["source"] if model else None)
            if source is not None:
                artifacts = model.get("artifact_sha256s", []) if model and model["source"] == source else []
                try:
                    forecast = self._forecast(source, request, artifacts)
                    prediction = forecast["forecast"]
                    result.update(calculation_receipts=forecast["executions"],
                                  source_sha256=hashlib.sha256(source.encode()).hexdigest(),
                                  input_sha256=forecast["input_sha256"])
                except ScientificExecutionError as error:
                    result["errors"].append("model calculation failed; this is not experimental evidence")
                    result["calculation_error"] = error.public_details
            else:
                result["notes"].append("No active model; virtual request may use explicit abstention")
        if prediction is not None:
            checks = forecast_issues(prediction, request, units=UNITS)
            result.update(prediction=prediction, forecast_targets=checks["targets"])
            result["errors"].extend(checks["errors"]); result["notes"].extend(checks["notes"])
        result["contract_ready"] = not result["errors"]
        result["limits"] = ["Historical conditional scenario; this preview establishes no current physical applicability"]
        return result

    def _prepare_simulation(self, args):
        preview = self._contract_preview(args["request"])
        if preview["errors"]:
            raise ValueError("; ".join(preview["errors"]))
        intent = super()._prepare_simulation(args)
        checks = forecast_issues(intent["forecast"], intent["request"], units=UNITS)
        if checks["errors"]:
            raise ValueError("; ".join(checks["errors"]))
        return {**intent, "simulation": NAME}

    def _apply_simulation(self, call_id, args, intent):
        rid = args["request_id"]
        if not self.simulation.store.has("request", rid):
            if (self.campaign.state()["active_model_id"] or NO_MODEL) != intent["model_id"]:
                raise ConflictError("active model changed after virtual prediction")
            if set(intent["evidence_ids"]) != {row["evidence_id"] for row in self.campaign.evidence()}:
                raise ConflictError("physical evidence changed after virtual prediction")
            self.simulation.store.set_meta("active_model_id", intent["model_id"])
        committed = self.simulation.submit(intent["request"], intent["forecast"], rid,
            call_id="virtual:" + call_id, expected_model_id=intent["model_id"],
            expected_evidence_ids=intent["simulation_evidence_ids"])
        pending = next(r for r in self.simulation.state()["requests"] if r["request_id"] == rid)
        artifacts = self.simulation_root / "executions" / hashlib.sha256(rid.encode()).hexdigest()[:24]
        if pending["active_execution_failure"]:
            return self._execution_failure(rid, artifacts, pending["active_execution_failure"])
        command = [self.owner_simulation["python"], "-B", "-m", "ndfeb_sps.cli", "fulfill-simulation",
                   "--state", str(self.simulation.store.path), "--request-id", rid,
                   "--runtime", self.owner_simulation["runtime"], "--artifacts", str(artifacts),
                   "--world-config", str(self.simulation_root / "reference_world.json"),
                   "--seed", str(self.owner_simulation["seed"])]
        process = subprocess.run(command, text=True, capture_output=True, env=self._environment(), check=False)
        if process.returncode:
            raise RuntimeError("native magnetic fulfillment failed: " + process.stderr[-3000:])
        result = json.loads(process.stdout)
        delivery_id = result.get("delivery_id")
        if not delivery_id:
            pending = next(r for r in self.simulation.state()["requests"] if r["request_id"] == rid)
            return self._execution_failure(rid, artifacts, pending["active_execution_failure"] or result)
        if delivery_id:
            self.simulation.release(delivery_id, "native-conditional-simulation", call_id="virtual-release:" + delivery_id)
        return {"status": "complete" if delivery_id else "execution_failed", "simulation": NAME,
                "request_id": rid, "delivery_id": delivery_id, "model_id": committed["model_id"],
                "prediction": committed["prediction"], "evidence_class": "conditional_computational",
                "origin": "synthetic", "physical_execution": False, "scientific_negative": False,
                "artifacts": [r for r in self.artifacts() if r["delivery_id"] == delivery_id],
                "retrieval": "inspect_state(section='simulation_magnetic'); read_artifact and compute/adopt_model artifact_sha256s bind these outputs"}

    def _execution_failure(self, request_id, artifacts, failure):
        diagnostics = []
        for receipt in sorted(artifacts.glob("native/native-*/*receipt.json")):
            try:
                raw = receipt.read_bytes()
                report = json.loads(raw)
            except (OSError, ValueError):
                continue
            if isinstance(report, dict) and report.get("validation_reasons"):
                diagnostics.append({"receipt_relative_path": str(receipt.relative_to(self.simulation_root)),
                                    "sha256": hashlib.sha256(raw).hexdigest(),
                                    "validation_reasons": report["validation_reasons"]})
        return {"status": "execution_failed", "request_id": request_id, "simulation": NAME,
                "scientific_negative": False, "physical_execution": False, "origin": "synthetic",
                "evidence_class": "conditional_computational", "failure": failure,
                "native_diagnostics": diagnostics, "artifacts": [],
                "retrieval": "inspect_state(section='simulation_magnetic') retains the failed request; corrected inputs require a new request ID"}
